// ---- Gate configuration ----

export const GATES = ["A1", "A2", "B1", "B2", "C1"];

// Below the first gate — a true beginner who cannot clear A1.
export const STARTER_LEVEL = "Starter";

// Pure-MCQ gates (A1/A2) pass at 60% correct (6/10) — unchanged from
// before this rebuild. Mixed gates (B1/B2/C1) pass at an average item
// score of 3.5/5 across all 10 items regardless of format — MCQ items are
// scored 5 (correct) or 1 (wrong) at record time specifically so they sit
// on the same scale as LLM-graded open items and can be averaged together.
export const MCQ_PASS_RATIO = 0.6;
export const OPEN_PASS_AVG = 3.5;

export const GATE_POOLS = {
  A1: { mcq: A1_MCQ },
  A2: { mcq: A2_MCQ },
  B1: { mcq: B1_MCQ, open: { vocab: B1_OPEN_VOCAB, grammar: B1_OPEN_GRAMMAR } },
  B2: { mcq: B2_MCQ, open: { vocab: B2_OPEN_VOCAB, grammar: B2_OPEN_GRAMMAR } },
  C1: { mcq: C1_MCQ, open: { vocab: C1_OPEN_VOCAB, grammar: C1_OPEN_GRAMMAR } },
};

// A gate is "mixed" if it has both an mcq and an open pool. A1/A2 have only
// mcq and are scored/sampled differently (see pickGateSet/gateOutcome in
// placementTest.js).
export const isMixedGate = (level) => !!(GATE_POOLS[level] && GATE_POOLS[level].open);
